const b = $('Merge webhooks').item.json.body;
const pr = $json;
const isReviewComment = !b.issue && !!b.pull_request;
const c = b.comment;
const body = (c && c.body) || '';
const m = body.match(/@([a-zA-Z0-9-]+)/);
const mentionedLogin = m ? m[1] : '';
const instruction = mentionedLogin ? body.replace(new RegExp('@' + mentionedLogin + '\\b', 'i'), '').trim() : body.trim();
const location = c && c.path ? ` at ${c.path}${(c.line || c.original_line) ? ':' + (c.line || c.original_line) : ''}` : '';
const diffBlock = c && c.diff_hunk ? `\n\nRelevant diff hunk:\n\`\`\`diff\n${c.diff_hunk}\n\`\`\`\n` : '';
const args = {
  surface: 'pr-address',
  repoOwner: b.repository.owner.login,
  repoName: b.repository.name,
  repoFull: b.repository.full_name,
  senderLogin: b.sender && b.sender.login,
  senderType: b.sender && b.sender.type,
  prNumber: isReviewComment ? b.pull_request.number : b.issue.number,
  branch: pr.head && pr.head.ref,
  baseRef: pr.base && pr.base.ref,
  headSha: pr.head && pr.head.sha,
  prAuthor: pr.user && pr.user.login,
  commentId: c && c.id,
  commentBody: body,
  commentUrl: (c && c.html_url) || '',
  path: (c && c.path) || null,
  line: (c && (c.line || c.original_line)) || null,
  diffHunk: (c && c.diff_hunk) || null,
  mentionedLogin,
  title: pr.title,
  bodyText: body,
};
let prompt;
if (mentionedLogin) {
  prompt = `You were @-mentioned by @${args.senderLogin} on PR #${args.prNumber}, branch ${args.branch}.

Instruction${location}:
---
${instruction}
---${diffBlock}

Follow the instruction exactly. Keep the change minimal. Commit with message: "address comment ${args.commentId} from @${args.senderLogin}". Do not rebase. Do not push — the workflow handles push.
`;
} else {
  prompt = `Address review feedback on PR #${args.prNumber}, branch ${args.branch}.

Reviewer comment${location}:
---
${args.commentBody}
---${diffBlock}

Make the smallest change that addresses the comment. Commit with message: "address review comment ${args.commentId}". Do not rebase. Do not push.
`;
}
args.promptB64 = Buffer.from(prompt, 'utf8').toString('base64');
return [{ json: { argsB64: Buffer.from(JSON.stringify(args), 'utf8').toString('base64') } }];
